builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        options.MapInboundClaims = false; // keep 'sub', 'email', 'roles'
        options.TokenValidationParameters = new TokenValidationParameters
        {
            RoleClaimType = "roles" // Azure AD / many IdPs use this name
        };
    });

// Now User.IsInRole("Admin") and RequireRole check 'roles' claim values

public class DbRoleClaimsTransformation(
    IPermissionService permissions) : IClaimsTransformation
{
    public async Task<ClaimsPrincipal> TransformAsync(ClaimsPrincipal principal)
    {
        if (principal.Identity?.IsAuthenticated != true)
            return principal;

        var clone = principal.Clone() as ClaimsPrincipal ?? principal;
        var identity = (ClaimsIdentity)clone.Identity!;

        var userId = principal.FindFirstValue("sub");
        if (userId is null) return clone;

        var roles = await permissions.GetRolesAsync(userId);
        foreach (var role in roles)
            identity.AddClaim(new Claim(ClaimTypes.Role, role));

        return clone;
    }
}

builder.Services.AddTransient<IClaimsTransformation, DbRoleClaimsTransformation>();

public class RolesArrayTransformation : IClaimsTransformation
{
    public Task<ClaimsPrincipal> TransformAsync(ClaimsPrincipal principal)
    {
        var identity = principal.Identity as ClaimsIdentity;
        if (identity is null || !identity.IsAuthenticated)
            return Task.FromResult(principal);

        var jsonRoles = identity.FindFirst("roles")?.Value;
        if (jsonRoles?.StartsWith('[') == true)
        {
            var roles = JsonSerializer.Deserialize<string[]>(jsonRoles)!;
            identity.RemoveClaim(identity.FindFirst("roles")!);
            foreach (var r in roles)
                identity.AddClaim(new Claim(ClaimTypes.Role, r));
        }
        return Task.FromResult(principal);
    }
}

