    {
        await next();
        if (ctx.Response.StatusCode == 403)
        {
            var claims = ctx.User.Claims
                .Select(c => $"{c.Type}={c.Value}");
            app.Logger.LogWarning("403 claims: {Claims}", string.Join(", ", claims));
        }
    });
